import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.2 candidate record","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.2 candidate record","docId":"releases.4.2.1-rc.2","translationKey":"releases.4.2.1-rc.2","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","translationRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","order":20},"headers":[],"relativePath":"en/releases/4.2.1-rc.2.md","filePath":"en/releases/4.2.1-rc.2.md","lastUpdated":1794591482000}'),i={name:"en/releases/4.2.1-rc.2.md"};function n(s,e,c,d,l,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="tiktools-421-rc2" tabindex="-1">TikTools 4.2.1-rc.2 <a class="header-anchor" href="#tiktools-421-rc2" aria-label="Permalink to &quot;TikTools 4.2.1-rc.2 {#tiktools-421-rc2}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Goal, status and prerequisites <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Goal, status and prerequisites {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Use RC2&#39;s historical notes to understand the correction for concurrent Changes reads reproduced in RC1. The candidate record covers Linux AppImage, DEB and portable packages built locally while Actions was disabled. It does not establish current download availability or a newly built Windows package. Choose assets from the <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">release list</a>, retain their checksum file and test with an isolated profile.</p><p>Cloud recovery and collaboration remain experimental. Nickname search still depends on backend <code>6a69c99</code> and migration <code>20261113000001_remote_invitation_recipients.sql</code>; the application package does not deploy those changes.</p><h2 id="correction-and-expected-behavior" tabindex="-1">Correction and expected behavior <a class="header-anchor" href="#correction-and-expected-behavior" aria-label="Permalink to &quot;Correction and expected behavior {#correction-and-expected-behavior}&quot;">​</a></h2><p>Changes/conflict lists and protocol selection share protocol observation instead of reserving the product mutation slot. Toolbar and panel reads can complete while an unrelated package journal operation occupies that slot. Write fences, account isolation and explicit migration decisions remain.</p><p>The account check rejects logout, pending transitions and replacement sessions. Reading a local comparison does not restore credentials or start a Cloud request. On failure the UI shows the native reason and a local reload action; this retry does not send, download or resolve a record.</p><h2 id="check-the-candidate" tabindex="-1">Check the candidate <a class="header-anchor" href="#check-the-candidate" aria-label="Permalink to &quot;Check the candidate {#check-the-candidate}&quot;">​</a></h2><ol><li>Record the displayed <code>4.2.1-rc.2</code> version and open Plugins → Changes in an isolated profile.</li><li>Open or reload the comparison from the toolbar and panel. A load failure should retain its reason rather than report that everything is synchronized.</li><li>Use the local retry and confirm that it reloads the comparison without changing pending queues or applying remote records.</li><li>Record account/session transitions separately. Compare with <a href="./4.2.1-rc.1.html">RC1&#39;s migration procedure</a> when reproducing an affected profile.</li></ol><h2 id="recorded-validation-and-recovery" tabindex="-1">Recorded validation and recovery <a class="header-anchor" href="#recorded-validation-and-recovery" aria-label="Permalink to &quot;Recorded validation and recovery {#recorded-validation-and-recovery}&quot;">​</a></h2><p>The original record describes a deterministic 32-reader regression, CloudAuth/sync/native/frontend checks, and startup of the optimized AppImage with an empty isolated profile. Installer content and portable archive checks were recorded. That startup did not test signed-in production synchronization or media playback.</p><p>The historical AppImage SHA-256 was <code>35fc26e7bc5875c5a3fe99bf6a84baf77af8ca63d1c8b8e61825881187d6091f</code>. It identifies that recorded file; use the checksum attached to the asset you actually download.</p><p>If loading still fails, keep the version, native error and request ID, then use <a href="./../user/preferences/troubleshooting.html">Diagnostics</a>. Preserve pending edits and conflicts. At RC2, Automations still used a local reference, Variables and Overlay section work was unfinished, and the historical SQLite lock holder remained unidentified. These notes do not assert that an older backend&#39;s missing people-search route has since been deployed.</p><p>The <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.2.md" target="_blank" rel="noreferrer">original release record</a> is retained as dated evidence. Return to the <a href="./">release index</a>.</p>',14)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
